      shield: 'M12 3l8 3v6c0 4.5-3.2 7.7-8 9-4.8-1.3-8-4.5-8-9V6l8-3zM9 12l2 2 4-4',
      gauge: 'M12 13l4-4M4.5 19a9 9 0 1 1 15 0M12 21h.01',
